tiles=[
    ('A',0,12,17), # frame 2, rightmost
    ('U',1,3,0),   # frame 8, leftmost of the overlapping pair
    ('B',5,12,5),  # frame 8, stopped behind U
    ('C',8,2,12),  # frame 2, stopped behind E
    ('D',14,7,0),  # frame 8, independent lane
    ('E',12,14,17),# frame 2, rightmost in its overlapping pair
]
out=[[4]*22 for _ in range(22)]
for name,y,x0,x1 in tiles:
    tile=[row[x0:x0+5] for row in grid[y:y+5]]
    assert len(tile)==5 and all(len(r)==5 for r in tile)
    for dy in range(5):
        for dx in range(5):
            yy,xx=y+dy,x1+dx
            if out[yy][xx]!=4:
                raise ValueError((name,yy,xx,out[yy][xx],tile[dy][dx]))
            out[yy][xx]=tile[dy][dx]
print('input nonbg, output nonbg:',sum(v!=4 for r in grid for v in r),sum(v!=4 for r in out for v in r))
for y,row in enumerate(out): print(y, row)
